# BLE 5.x Physical Layer Channel Mapping & Spectrum Geometry Engine
class BLEPhysicalChannelEngine:
    TOTAL_CHANNELS = 40
    PRIMARY_ADV_CHANNELS = {37: 2402.0, 38: 2426.0, 39: 2480.0}

    @classmethod
    def get_channel_frequency_mhz(cls, rf_channel: int) -> float:
        if not (0 <= rf_channel <= 39):
            raise ValueError(f"Invalid BLE RF Channel {rf_channel}. Valid range: 0-39.")
        return 2402.0 + 2.0 * rf_channel

    @classmethod
    def classify_channel(cls, rf_channel: int) -> dict:
        freq = cls.get_channel_frequency_mhz(rf_channel)
        if rf_channel in cls.PRIMARY_ADV_CHANNELS:
            role = "PRIMARY_ADVERTISING"
            description = f"Dedicated Broadcast/Discovery (Ch {rf_channel} at {freq:.1f} MHz)"
        else:
            role = "GENERAL_DATA"
            # Map RF channel to data index (0-36)
            description = f"Connected Data / Secondary Adv (Ch {rf_channel} at {freq:.1f} MHz)"

        return {
            "rf_channel": rf_channel,
            "center_freq_mhz": freq,
            "role": role,
            "bandwidth_mhz": 2.0,
            "description": description
        }

engine = BLEPhysicalChannelEngine()
print("=== BLE 5.x 2.4 GHz RF Channel Allocation Architecture ===")
print("Primary Advertising Channels (Dedicated Guard-Band Shielding):")
for ch in [37, 38, 39]:
    info = engine.classify_channel(ch)
    print(f"  RF Ch {ch:2d}: {info['center_freq_mhz']:.1f} MHz -> {info['description']}")

print("\nSample Data Channels (Frequency Hopping Pool):")
for ch in [0, 10, 20, 30, 36]:
    info = engine.classify_channel(ch)
    print(f"  RF Ch {ch:2d}: {info['center_freq_mhz']:.1f} MHz -> {info['description']}")

# BLE Legacy Advertising Data (AdvData) Binary Encoder & Decoder
import struct

class BLEAdvDataParser:
    AD_TYPE_FLAGS = 0x01
    AD_TYPE_UUID16_COMPLETE = 0x03
    AD_TYPE_COMPLETE_LOCAL_NAME = 0x09
    AD_TYPE_TX_POWER = 0x0A
    AD_TYPE_MANUFACTURER_DATA = 0xFF

    @classmethod
    def serialize_ad_structures(cls, structures: list[tuple[int, bytes]]) -> bytes:
        pdu = bytearray()
        for ad_type, data in structures:
            length = len(data) + 1  # 1 byte for AD Type + len(data)
            pdu.append(length)
            pdu.append(ad_type)
            pdu.extend(data)
        if len(pdu) > 31:
            raise ValueError(f"AdvData payload exceeds 31-byte legacy limit! ({len(pdu)} bytes)")
        return bytes(pdu)

    @classmethod
    def parse_ad_structures(cls, payload: bytes) -> dict:
        parsed = {"flags": None, "complete_name": None, "uuids_16": [], "tx_power_dbm": None, "manufacturer_raw": None}
        idx = 0
        while idx < len(payload):
            if idx >= len(payload):
                break
            length = payload[idx]
            if length == 0:
                break  # Trailing zero padding
            if idx + 1 + length > len(payload) + 1:
                break  # Malformed structure
            ad_type = payload[idx + 1]
            data = payload[idx + 2 : idx + 1 + length]

            if ad_type == cls.AD_TYPE_FLAGS:
                parsed["flags"] = data[0] if len(data) > 0 else 0
            elif ad_type == cls.AD_TYPE_COMPLETE_LOCAL_NAME:
                parsed["complete_name"] = data.decode("utf-8", errors="replace")
            elif ad_type == cls.AD_TYPE_UUID16_COMPLETE:
                # 16-bit UUIDs are little-endian 2-byte values
                for u_idx in range(0, len(data), 2):
                    uuid16 = struct.unpack("<H", data[u_idx:u_idx+2])[0]
                    parsed["uuids_16"].append(f"0x{uuid16:04X}")
            elif ad_type == cls.AD_TYPE_TX_POWER:
                parsed["tx_power_dbm"] = struct.unpack("<b", data)[0]
            elif ad_type == cls.AD_TYPE_MANUFACTURER_DATA:
                company_id = struct.unpack("<H", data[:2])[0] if len(data) >= 2 else 0
                parsed["manufacturer_raw"] = {"company_id": f"0x{company_id:04X}", "payload_hex": data[2:].hex()}

            idx += 1 + length
        return parsed

# Assemble sample 31-byte legacy advertising payload for an Industrial Vibration Node
ad_list = [
    (0x01, bytes([0x06])),                                     # Flags: LE General + No BR/EDR
    (0x03, struct.pack("<H", 0x181A)),                          # Complete 16-bit UUID: Environmental Sensing (0x181A)
    (0x0A, struct.pack("<b", 4)),                               # TX Power: +4 dBm
    (0x09, b"PumpSensor"),                                      # Complete Local Name: PumpSensor (10 bytes)
    (0xFF, struct.pack("<H", 0x0059) + bytes([0xAA, 0x01, 0x4B])) # Nordic Semi ID (0x0059) + 3 bytes telemetry
]

encoded_pdu = BLEAdvDataParser.serialize_ad_structures(ad_list)
decoded = BLEAdvDataParser.parse_ad_structures(encoded_pdu)

print("=== BLE Legacy 31-Byte Advertising Binary Serialization & Parsing ===")
print(f"Serialized AdvData ({len(encoded_pdu)}/31 bytes): {encoded_pdu.hex().upper()}")
print(f"Decoded Flags:        0x{decoded['flags']:02X} (LE General Discoverable, BR/EDR Not Supported)")
print(f"Decoded Complete Name:{decoded['complete_name']}")
print(f"Decoded Services:     {decoded['uuids_16']}")
print(f"Decoded TX Power:     {decoded['tx_power_dbm']} dBm")
print(f"Decoded Mfr Specific: Company {decoded['manufacturer_raw']['company_id']}, Data: {decoded['manufacturer_raw']['payload_hex']}")

# BLE Scanner Duty Cycle & Discovery Probability Simulator
class BLEScannerModel:
    SLOT_MS = 0.625

    def __init__(self, scan_interval_ms: float, scan_window_ms: float, rx_current_ma: float = 7.0):
        if scan_window_ms > scan_interval_ms:
            raise ValueError("Scan window cannot exceed scan interval.")
        self.scan_interval_ms = scan_interval_ms
        self.scan_window_ms = scan_window_ms
        self.rx_current_ma = rx_current_ma

    @property
    def duty_cycle_pct(self) -> float:
        return (self.scan_window_ms / self.scan_interval_ms) * 100.0

    @property
    def average_rx_current_ma(self) -> float:
        return self.rx_current_ma * (self.scan_window_ms / self.scan_interval_ms)

    def calculate_discovery_overlap_prob(self, adv_interval_ms: float, event_toa_ms: float = 1.5) -> dict:
        # Probability of overlap between random advertising event and scanning window
        # Overlap occurs if adv event starts within [t_scan_start - toa, t_scan_start + window]
        effective_window = self.scan_window_ms + event_toa_ms
        prob_per_interval = min(1.0, effective_window / self.scan_interval_ms)

        # Expected discovery latency (50th and 90th percentile events)
        # Using geometric distribution approximation
        return {
            "duty_cycle_pct": self.duty_cycle_pct,
            "avg_current_ma": self.average_rx_current_ma,
            "overlap_prob_per_adv": prob_per_interval,
            "expected_discovery_events": 1.0 / prob_per_interval if prob_per_interval > 0 else float("inf")
        }

# Compare Continuous Scanning vs Low-Power Duty-Cycled Scanning
scanners = {
    "Continuous (100%)": BLEScannerModel(scan_interval_ms=100.0, scan_window_ms=100.0),
    "Aggressive (25%)":  BLEScannerModel(scan_interval_ms=160.0, scan_window_ms=40.0),
    "Low-Power (5%)":    BLEScannerModel(scan_interval_ms=1280.0, scan_window_ms=64.0)
}

print("=== BLE Scanner Parameter & Duty Cycle Energy Optimization ===")
adv_interval = 200.0  # Peripheral advertises every 200 ms
for name, sc in scanners.items():
    stats = sc.calculate_discovery_overlap_prob(adv_interval)
    print(f"Mode: {name:18s} | Duty: {stats['duty_cycle_pct']:5.1f}% | Avg Current: {stats['avg_current_ma']:5.2f} mA | "
          f"Hit Prob: {stats['overlap_prob_per_adv']:5.3f} | Exp Adv Bursts: {stats['expected_discovery_events']:4.1f}")

class BLESupervisionInvariantValidator:
    MIN_INTERVAL_MS = 7.5
    MAX_INTERVAL_MS = 4000.0
    MIN_TIMEOUT_MS = 100.0
    MAX_TIMEOUT_MS = 32000.0
    MAX_LATENCY = 499

    @classmethod
    def validate_connection_parameters(cls, interval_ms: float, latency: int, 
                                       timeout_ms: float, platform: str = "BLUETOOTH_SIG") -> dict:
        errors = []
        warnings = []
        if not (cls.MIN_INTERVAL_MS <= interval_ms <= cls.MAX_INTERVAL_MS):
            errors.append(f"Interval {interval_ms:.2f}ms outside valid range [7.5ms, 4000.0ms]")
        if not (0 <= latency <= cls.MAX_LATENCY):
            errors.append(f"Latency {latency} outside valid range [0, 499]")
        if not (cls.MIN_TIMEOUT_MS <= timeout_ms <= cls.MAX_TIMEOUT_MS):
            errors.append(f"Timeout {timeout_ms:.0f}ms outside valid range [100ms, 32000ms]")

        min_allowed_timeout_sig = (1 + latency) * interval_ms * 2.0
        if timeout_ms <= min_allowed_timeout_sig:
            errors.append(
                f"VIOLATION: Supervision Timeout ({timeout_ms:.0f}ms) must be strictly greater than "
                f"(1 + Latency) * Interval * 2 ({min_allowed_timeout_sig:.1f}ms). Risk: False Drops!"
            )

        if platform == "APPLE_IOS":
            min_apple_timeout = (1 + latency) * interval_ms * 3.0
            if timeout_ms < min_apple_timeout:
                errors.append(f"APPLE GUIDELINE VIOLATION: Timeout must be >= (1+L)*Interval*3 ({min_apple_timeout:.1f}ms)")
            if timeout_ms > 6000.0:
                errors.append(f"APPLE GUIDELINE VIOLATION: Supervision Timeout cannot exceed 6.0 seconds (got {timeout_ms/1000:.1f}s)")
            if interval_ms < 15.0:
                warnings.append("Apple recommends Interval >= 15.0ms for general BLE accessories.")

        return {
            "platform": platform,
            "is_valid": len(errors) == 0,
            "min_safe_timeout_ms": min_allowed_timeout_sig,
            "errors": errors,
            "warnings": warnings
        }

# Evaluate 3 Test Parameter Vectors
test_cases = [
    # Case 1: Buggy configuration (Timeout too short)
    {"name": "Faulty Firmware Vector A", "interval": 100.0, "latency": 4, "timeout": 500.0, "plat": "BLUETOOTH_SIG"},
    # Case 2: Compliant standard SIG parameters
    {"name": "Compliant Standard Vector B", "interval": 50.0, "latency": 4, "timeout": 2000.0, "plat": "BLUETOOTH_SIG"},
    # Case 3: Rejected by Apple iOS Guidelines (Timeout > 6s)
    {"name": "Apple Guideline Conflict Vector C", "interval": 200.0, "latency": 15, "timeout": 12000.0, "plat": "APPLE_IOS"}
]

print("=== BLE Supervision Timeout Invariant Verification Engine ===")
for tc in test_cases:
    res = BLESupervisionInvariantValidator.validate_connection_parameters(
        tc["interval"], tc["latency"], tc["timeout"], tc["plat"]
    )
    status_str = "VALID (COMPLIANT)" if res["is_valid"] else "INVALID (REJECTED)"
    print(f"Test: {tc['name']} -> {status_str}")
    print(f"  Params: Interval={tc['interval']:.1f}ms, Latency={tc['latency']}, Timeout={tc['timeout']:.0f}ms")
    print(f"  Required Min Timeout: > {res['min_safe_timeout_ms']:.1f} ms")
    for err in res["errors"]:
        print(f"  [ERROR] {err}")
    for warn in res["warnings"]:
        print(f"  [WARN]  {warn}")
    print()

# BLE Multi-Role Link Layer State Machine Formal Transition Engine
class BLELinkLayerFSM:
    VALID_STATES = {"STANDBY", "ADVERTISING", "SCANNING", "INITIATING", "CONNECTION_CENTRAL", "CONNECTION_PERIPHERAL"}

    TRANSITIONS = {
        "STANDBY": {"ADVERTISING", "SCANNING", "INITIATING"},
        "ADVERTISING": {"STANDBY", "CONNECTION_PERIPHERAL"},
        "SCANNING": {"STANDBY"},
        "INITIATING": {"STANDBY", "CONNECTION_CENTRAL"},
        "CONNECTION_CENTRAL": {"STANDBY"},
        "CONNECTION_PERIPHERAL": {"STANDBY"}
    }

    def __init__(self, device_id: str):
        self.device_id = device_id
        self.state = "STANDBY"
        self.state_history = [("STANDBY", 0.0)]
        self.active_links = {}

    def transition_to(self, new_state: str, timestamp_ms: float) -> str:
        if new_state not in self.VALID_STATES:
            raise ValueError(f"Unknown state: {new_state}")
        if new_state not in self.TRANSITIONS[self.state]:
            raise IllegalStateTransitionError(
                f"Illegal transition: {self.state} -> {new_state} not permitted in Bluetooth Core Spec!"
            )
        old_state = self.state
        self.state = new_state
        self.state_history.append((new_state, timestamp_ms))
        return f"[{self.device_id}] State Transition at {timestamp_ms:.1f}ms: {old_state} ===> {new_state}"

class IllegalStateTransitionError(Exception):
    pass

fsm = BLELinkLayerFSM("Gateway-01")
print("=== BLE Link Layer State Machine Formal Verification ===")
print(fsm.transition_to("ADVERTISING", 10.0))
print(fsm.transition_to("CONNECTION_PERIPHERAL", 35.5))
print(fsm.transition_to("STANDBY", 120.0))
print(fsm.transition_to("INITIATING", 125.0))
print(fsm.transition_to("CONNECTION_CENTRAL", 142.0))
print(fsm.transition_to("STANDBY", 300.0))

# Verify that illegal transition raises exception
try:
    fsm.transition_to("CONNECTION_PERIPHERAL", 305.0)  # Cannot go STANDBY -> CONNECTION_PERIPHERAL directly
except IllegalStateTransitionError as e:
    print(f"Trapped Illegal Transition: {e}")
